<span class="line">        <span class="token keyword">new</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token constructor-invocation class-name">BatchId</span><span class="token punctuation">(</span>Guid<span class="token punctuation">.</span><span class="token function">CreateVersion7</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span> recipeId<span class="token punctuation">,</span> volume<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
